import torch


def q565(gradients, clip):
    if not gradients or clip <= 0:
        raise ValueError("invalid gradients/clip")
    b = gradients[0].shape[0]
    if any((g.shape[0] != b for g in gradients)):
        raise ValueError("batch mismatch")
    norm = torch.sqrt(
        sum((g.reshape(b, -1).square().sum(1) for g in gradients))
    )
    factor = (clip / norm.clamp_min(1e-12)).clamp(max=1)
    return (
        [g * factor.reshape((b,) + (1,) * (g.ndim - 1)) for g in gradients],
        norm,
    )
